import math

def get_divisors(n):
    divs = []
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.append(i)
            if i * i != n:
                divs.append(n // i)
    divs.sort()
    return divs

def count_divisors(n):
    count = 0
    for i in range(1, n + 1):
        if n % i == 0:
            count += 1
    return count

def check_solution(n):
    divs = get_divisors(n)
    tau_n = len(divs)

    if tau_n < 5:
        return None

    # Divisors are 1, d2, d3, d4, d5, ...
    # a = d2 (second smallest)
    # b = d3 (third smallest)
    # c = d5 (fifth smallest)
    a = divs[1]
    b = divs[2]
    c = divs[4]

    # Check the simplified equation: n = ab + ac + bc
    lhs = a * b + a * c + b * c
    rhs = n

    if lhs == rhs:
        return {'n': n, 'tau(n)': tau_n, 'a': a, 'b': b, 'c': c}
    else:
        return None

solutions = []
for n in range(57, 200):
    result = check_solution(n)
    if result:
        solutions.append(result)

print(solutions)
